    let entries = trees.get(revision)
    if (!entries) {
      entries = new Map(
        git(root, ['ls-tree', '-r', '-z', revision])
          .split('\0')
          .filter(Boolean)
          .map((row) => {
            const [metadata, path] = row.split('\t'),
              [mode, , oid] = (metadata ?? '').split(' ')
            if (!mode || !oid || !path) throw new Error('Malformed required Git tree')
            return [path, { mode, oid }]
